template.query:
query ExportTodos($status: String, $category: String, $priority: String, $includeCompleted: Boolean = false) {
  exportNodes(
    tableId: "58"
    filters: [
      { attributeName: "status", value: $status }
      { attributeName: "category", value: $category }
      { attributeName: "priority", value: $priority }
    ]
    options: {
      format: "JSON"
      includeMetadata: true
      dateFormat: "ISO"
    }
  ) {
    data {
      id
      content
      createdAt
      attributes {
        name
        value
      }
    }
    metadata {
      exportedAt
      totalCount
      filters
    }
    summary {
      byStatus {
        status
        count
      }
      byCategory {
        category
        count
      }
      byPriority {
        priority
        count
      }
    }
  }
}
